using System.Collections.Generic;
using UnityEngine;

public class InventorySystem : MonoBehaviour
{
    // O(1) para insertar y buscar por ID
    private Dictionary<string, Item> _items = new Dictionary<string, Item>();

    // Caché del ítem equipado — se actualiza solo cuando cambia el equipo
    private Item _activeAmulet;

    // O(1) — acceso directo por clave
    public Item GetItem(string id)
    {
        _items.TryGetValue(id, out Item item);
        return item;
    }

    public void AddItem(Item item)
    {
        _items[item.id] = item;
    }

    // Llamado solo cuando el jugador equipa o desequipa
    public void OnEquipChanged()
    {
        _items.TryGetValue("speed_amulet", out _activeAmulet);
    }

    // Update ya no busca — solo aplica el bono si hay caché válida
    private void Update()
    {
        if (_activeAmulet != null && _activeAmulet.isEquipped)
        {
            PlayerStats.Instance.ApplySpeedBonus(_activeAmulet.value);
        }
    }
}

