            PlayerPrefs.SetString($"item_{i}_id",       items[i].id);
            PlayerPrefs.SetInt($"item_{i}_qty",         items[i].quantity);
            PlayerPrefs.SetFloat($"item_{i}_durability", items[i].durability);
