    {
        int count = PlayerPrefs.GetInt("inventory_count", 0);
        var items = new List<Item>();

        for (int i = 0; i < count; i++)
        {
            items.Add(new Item
            {
                id         = PlayerPrefs.GetString($"item_{i}_id"),
                quantity   = PlayerPrefs.GetInt($"item_{i}_qty"),
                durability = PlayerPrefs.GetFloat($"item_{i}_durability")
            });
        }

        return items;
    }
