public class AbilityManager : MonoBehaviour
{
    // Un par de variables por habilidad — 2 campos × N habilidades
    private bool  _isDashOnCooldown;
    private float _dashCooldownEnd;
    private bool  _isShieldOnCooldown;
    private float _shieldCooldownEnd;
    private bool  _isGrenadeOnCooldown;
    private float _grenadeCooldownEnd;
    private bool  _isChargeOnCooldown;
