    {
        // Lógica idéntica repetida 4 veces
        if (_isDashOnCooldown && Time.time >= _dashCooldownEnd)
            _isDashOnCooldown = false;

        if (_isShieldOnCooldown && Time.time >= _shieldCooldownEnd)
            _isShieldOnCooldown = false;

        if (_isGrenadeOnCooldown && Time.time >= _grenadeCooldownEnd)
            _isGrenadeOnCooldown = false;

        if (_isChargeOnCooldown && Time.time >= _chargeCooldownEnd)
            _isChargeOnCooldown = false;
    }

