    {
        return ability switch
        {
            "dash"   => !_isDashOnCooldown,
            "shield" => !_isShieldOnCooldown,
            "grenade"=> !_isGrenadeOnCooldown,
            "charge" => !_isChargeOnCooldown,
            _        => false
