// AbilityManager.cs — Dictionary universal, sin switch, extensible sin tocar código
using System.Collections.Generic;
using UnityEngine;

public class AbilityManager : MonoBehaviour
{
    // Una sola estructura para N habilidades
    // Valor = Time.time en que termina el cooldown (0 = disponible desde el inicio)
    private Dictionary<string, float> _cooldownEndTimes = new Dictionary<string, float>();

    // Update eliminado — CanUse comprueba en tiempo real con Time.time
    // No hay bool que mantener en sincronía

    // Funciona para CUALQUIER habilidad sin agregar código
    public bool CanUse(string ability)
    {
        if (_cooldownEndTimes.TryGetValue(ability, out float endTime))
            return Time.time >= endTime;

        return true; // Si no hay registro, la habilidad está disponible
    }

    // Registra o actualiza el cooldown — una sola línea por habilidad
    public void TriggerCooldown(string ability, float duration)
    {
        _cooldownEndTimes[ability] = Time.time + duration;
    }

    // Opcional: cuánto tiempo falta para que termine el cooldown (para UI)
    public float GetRemainingCooldown(string ability)
    {
        if (_cooldownEndTimes.TryGetValue(ability, out float endTime))
            return Mathf.Max(0f, endTime - Time.time);

        return 0f;
    }
}

