// WaveManager.cs — lee datos y ejecuta con Coroutine
using UnityEngine;
using System.Collections;

public class WaveManager : MonoBehaviour
{
    [SerializeField] private WaveData   _waveData;
    [SerializeField] private Transform  _spawnPoint;

    private void Start() => StartCoroutine(RunWaves());

    private IEnumerator RunWaves()
    {
        foreach (WaveEntry wave in _waveData.waves)
        {
            yield return new WaitForSeconds(wave.delayBeforeWave);

            foreach (SpawnGroup group in wave.groups)
                yield return StartCoroutine(SpawnGroup(group));
        }
    }

    private IEnumerator SpawnGroup(SpawnGroup group)
    {
        for (int i = 0; i < group.count; i++)
        {
            Instantiate(group.enemyPrefab, _spawnPoint.position, Quaternion.identity);
            yield return new WaitForSeconds(group.timeBetweenSpawns);
        }
    }
}

