// ICommand.cs — interfaz base para todas las acciones reversibles
public interface ICommand
{
    bool CanExecute();
    void Execute();
    void Undo();
}

// BuyCommand.cs — encapsula la transacción de compra
public class BuyCommand : ICommand
{
    private readonly InventorySystem _inventory;
    private readonly ItemData        _item;

    private bool _executed = false;

    public BuyCommand(InventorySystem inventory, ItemData item)
    {
        _inventory = inventory;
        _item      = item;
    }

    // Valida TODAS las condiciones antes de tocar datos
    public bool CanExecute()
    {
        return _inventory.Gold >= _item.price
            && _inventory.HasSpace();
    }

    // Solo se llama si CanExecute() == true
    public void Execute()
    {
        _inventory.RemoveGold(_item.price);
        _inventory.AddItem(_item);
        _executed = true;
    }

    // Revierte exactamente lo que Execute() hizo
    public void Undo()
    {
        if (!_executed) return;
        _inventory.RemoveItem(_item);
        _inventory.AddGold(_item.price);
        _executed = false;
    }
}

