// UIStateManager.cs — State Machine con enum, sin polling, sin estados imposibles
using UnityEngine;

public enum UIState
{
    MainMenu,
    Loading,
    Playing,
    Paused,
    GameOver
}

public class UIStateManager : MonoBehaviour
{
    public static UIStateManager Instance;

    // Un solo campo — solo un estado válido a la vez por definición del tipo
    private UIState _currentState = UIState.MainMenu;

    public UIState CurrentState => _currentState;

    private void Awake() => Instance = this;

    // No hay Update — la UI reacciona al cambio de estado, no lo pollea

    private void TransitionTo(UIState newState)
    {
        if (_currentState == newState) return;

        // Desactiva la vista actual
        ExitState(_currentState);

        _currentState = newState;

        // Activa la nueva vista
        EnterState(_currentState);
    }

    private void ExitState(UIState state)
    {
        switch (state)
        {
            case UIState.MainMenu:  HideMainMenu();       break;
            case UIState.Loading:   HideLoadingScreen();  break;
            case UIState.Playing:   HideHUD();            break;
            case UIState.Paused:    HidePauseMenu();      break;
            case UIState.GameOver:  HideGameOverScreen(); break;
        }
    }

    private void EnterState(UIState state)
    {
        switch (state)
        {
            case UIState.MainMenu:  ShowMainMenu();       break;
            case UIState.Loading:   ShowLoadingScreen();  break;
            case UIState.Playing:   ShowHUD();            break;
            case UIState.Paused:    ShowPauseMenu();      break;
            case UIState.GameOver:  ShowGameOverScreen(); break;
        }
    }

    // API pública con nombres de intención explícita
    public void StartGame()   => TransitionTo(UIState.Loading);
    public void OnLoadDone()  => TransitionTo(UIState.Playing);
    public void PauseGame()   => TransitionTo(UIState.Paused);
    public void ResumeGame()  => TransitionTo(UIState.Playing);
    public void GameOver()    => TransitionTo(UIState.GameOver);
