        CraftingRecipe recipe = System.Array.Find(_recipes, r => r.recipeId == recipeId);
        if (recipe == null) return false;

        // Verifica TODOS los ingredientes sin mencionar ningún nombre específico
        bool hasAll = recipe.inputs.All(ing => Has(ing.itemId, ing.quantity));
        if (!hasAll) return false;

        // Consume ingredientes y entrega el resultado
        foreach (Ingredient ing in recipe.inputs)
            Remove(ing.itemId, ing.quantity);

        Give(recipe.output.id, recipe.outputQuantity);
        return true;
    }

