// InputHandler.cs — graba y reproduce
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class InputHandler : MonoBehaviour
{
    [SerializeField] private CarController _car;

    private List<IPlayerCommand> _recording  = new List<IPlayerCommand>();
    private bool                  _isRecording = false;
    private bool                  _isReplaying = false;

    public void StartRecording()
    {
        _recording.Clear();
        _isRecording = true;
    }

    public void StopRecording()
    {
        _isRecording = false;
    }

    public void StartReplay()
    {
        if (_isReplaying) return;
        StartCoroutine(PlaybackRoutine());
    }

    private IEnumerator PlaybackRoutine()
    {
        _isReplaying = true;
        float startTime = Time.time;

        foreach (IPlayerCommand cmd in _recording)
        {
            // Espera hasta que corresponda ejecutar este comando
            float waitUntil = startTime + cmd.Timestamp;
            yield return new WaitUntil(() => Time.time >= waitUntil);
            cmd.Execute(_car);
        }

        _isReplaying = false;
    }

    private void Update()
    {
        if (_isReplaying) return; // Durante replay no procesa input real

        float steer    = Input.GetAxis("Horizontal");
        float throttle = Input.GetAxis("Vertical");
        bool  brake    = Input.GetButton("Jump");

        var cmd = new DriveCommand(Time.time, steer, throttle, brake);
        cmd.Execute(_car);

        if (_isRecording)
            _recording.Add(cmd);
    }
}

