// LootTable.cs — ScriptableObject con pesos relativos, editable sin código
using System;
using UnityEngine;

[CreateAssetMenu(fileName = "LootTable_", menuName = "Loot/LootTable")]
public class LootTable : ScriptableObject
{
    public LootEntry[] entries;

    // Devuelve el prefab ganador según los pesos relativos
    public GameObject Roll()
    {
        if (entries == null || entries.Length == 0) return null;

        // Suma total de pesos — no importa si suman 100 o 1000
        float totalWeight = 0f;
        foreach (LootEntry entry in entries)
            totalWeight += entry.weight;

        // Sorteo en el rango [0, totalWeight)
        float roll = UnityEngine.Random.Range(0f, totalWeight);

        // Encuentra el ganador acumulando pesos
        float cumulative = 0f;
        foreach (LootEntry entry in entries)
        {
            cumulative += entry.weight;
            if (roll < cumulative)
                return entry.prefab;
        }

        // Fallback: último elemento
        return entries[entries.Length - 1].prefab;
    }
}

[Serializable]
public class LootEntry
{
    public string     label;   // Nombre descriptivo para el Inspector
    public GameObject prefab;
    public float      weight;  // Peso relativo — no necesita sumar 100
}

// LootSystem.cs — completamente genérico, funciona con cualquier LootTable
using UnityEngine;

public class LootSystem : MonoBehaviour
{
    // Cada tipo de enemigo puede tener su propia tabla
    [SerializeField] private LootTable _lootTable;

    public void SpawnLoot(Vector3 position)
    {
        GameObject prefab = _lootTable.Roll();

        if (prefab != null)
            Instantiate(prefab, position, Quaternion.identity);
    }
}
